<article class="product-card"><div class="product-photo"><a href="/product/<?=e($item['slug'])?>"><img src="<?=e(image_path($item))?>" srcset="<?=e(image_srcset($item))?>" sizes="(max-width: 800px) 45vw, 22vw" alt="<?=e($item['name'])?>" loading="lazy" width="640" height="800"></a><span class="product-tag"><?= $item['sale_price']!==null ? 'SPECIAL PRICE' : ($item['featured']?'WIKI FAVORITE':'NEW')?></span><form method="post" action="/api/action" data-ajax><?=csrf_field()?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="product_id" value="<?=e($item['id'])?>"><button class="heart" aria-label="Save <?=e($item['name'])?> to wishlist">♡</button></form><a class="quick-view" href="/product/<?=e($item['slug'])?>">Discover product ↗</a></div><div class="product-meta"><span><?=e($item['type']==='scents'?'EAU DE PARFUM · UNISEX':'EVERYDAY ESSENTIALS')?></span><span><?= $item['rating'] ? '★ '.number_format((float)$item['rating'],1) : 'WIKI' ?></span></div><h3><a href="/product/<?=e($item['slug'])?>"><?=e(str_replace('WIKI ','',$item['name']))?></a></h3><p class="product-price"><?=money((int)($item['sale_price']??$item['price']))?> <?php if($item['sale_price']!==null): ?><del><?=money((int)$item['price'])?></del><?php endif ?></p><div class="swatches" aria-label="<?= $item['type']==='scents'?'Available in 30ml, 50ml and 100ml':'Available in Black, Beige and White' ?>"><?php if($item['type']==='scents'): ?><small>30 ml / 50 ml / 100 ml</small><?php else: ?><i></i><i></i><i></i><small>3 colors</small><?php endif ?></div></article>
